import io.circe.syntax._
import grackle.Problem

// message + locations + path
Problem("foo", List(1 -> 2, 5 -> 6), List("bar", "baz")).asJson
// => { "message":"foo",
//      "locations":[{"line":1,"col":2},{"line":5,"col":6}],
//      "path":["bar","baz"] }

// message only (empty locations/path/extensions are omitted)
Problem("foo").asJson  // => { "message":"foo" }

// human-readable form
Problem("foo", List(1 -> 2, 5 -> 6), List("bar", "baz")).toString
// => "foo (at bar/baz: 1..2, 5..6)"

// QueryDirectivesMapping (ValueMapping[IO]) with an @upperCase directive elaborator
// that yields Elab.warning when applied to a non-String field.
val query = """
  query { user { name @upperCase  handle  age @upperCase } }
"""
val expected = json"""
  {
    "errors" : [ { "message" : "'upperCase' directive may only be applied to fields of type String" } ],
    "data"   : { "user" : { "name" : "MARY", "handle" : "mary", "age" : 42 } }
  }
"""
QueryDirectivesMapping.compileAndRun(query)  // IO[Json] == expected

import cats.effect.IO
import grackle.{Result, ResultT}

val rt: ResultT[IO, Int] =
  for {
    a <- ResultT.fromResult[IO, Int](Result.success(1))
    b <- ResultT.liftF(IO.pure(2))
    c <- ResultT.warning[IO, Int]("slow path", 3)
  } yield a + b + c

val out: IO[Result[Int]] = rt.value   // IO(Result.Warning(NEC(Problem("slow path")), 6))
